3	import React, { useState } from "react";
4	import { motion, AnimatePresence } from "framer-motion";
5	import { Plus } from "lucide-react";
6	import { BRAND, FONT, SHADOW, ACCENT_MAP } from "@/lib/brand";
7	import type { AccentKey } from "@/lib/brand";
8	
9	interface FAQItem {
10	  q: string;
11	  a: string;
12	}
13	
14	interface FAQAccordionProps {
15	  items: FAQItem[];
16	  defaultOpenIndex?: number;
17	  accent?: AccentKey;
18	}
19	
20	interface FAQRowProps {
21	  item: FAQItem;
22	  index: number;
23	  isOpen: boolean;
24	  onToggle: () => void;
25	  accentColor: string;
26	}
27	
28	function FAQRow({ item, index, isOpen, onToggle, accentColor }: FAQRowProps) {
29	  return (
30	    <div
31	      style={{
32	        borderBottom: `1px solid ${BRAND.borderSoft}`,
33	      } as React.CSSProperties}
34	    >
35	      <button
36	        type="button"
37	        onClick={onToggle}
38	        style={{
39	          width: "100%",
40	          display: "flex",
41	          alignItems: "center",
42	          gap: 16,
43	          padding: "20px 24px",
44	          background: "none",
45	          border: "none",
46	          cursor: "pointer",
47	          textAlign: "left",
48	        } as React.CSSProperties}
49	      >
50	        <span
51	          style={{
52	            fontFamily: FONT.mono,
53	            fontSize: 12,
54	            fontWeight: 600,
55	            color: accentColor,
56	            minWidth: 20,
57	            flexShrink: 0,
58	          } as React.CSSProperties}
59	        >
60	          {String(index + 1).padStart(2, "0")}
61	        </span>
62	
63	        <span
64	          style={{
65	            fontFamily: FONT.sans,
66	            fontSize: 17,
67	            fontWeight: 700,
68	            color: BRAND.onyx,
69	            lineHeight: 1.3,
70	            letterSpacing: "-0.01em",
71	            flex: 1,
72	          } as React.CSSProperties}
73	        >
74	          {item.q}
75	        </span>
76	
77	        <div
78	          style={{
79	            width: 32,
80	            height: 32,
81	            borderRadius: "50%",
82	            background: isOpen ? accentColor : BRAND.boneDeep,
83	            display: "flex",
84	            alignItems: "center",
85	            justifyContent: "center",
86	            flexShrink: 0,
87	            transition: "background 0.2s ease",
88	          } as React.CSSProperties}
89	        >
90	          <motion.div
91	            animate={{ rotate: isOpen ? 45 : 0 }}
92	            transition={{ duration: 0.2, ease: [0.22, 1, 0.36, 1] }}
93	          >
94	            <Plus
95	              size={16}
96	              color={isOpen ? BRAND.bone : BRAND.stoneDark}
97	              strokeWidth={2.2}
98	            />
99	          </motion.div>
100	        </div>
101	      </button>
102	
103	      <AnimatePresence initial={false}>
104	        {isOpen && (
105	          <motion.div
106	            key="answer"
107	            initial={{ height: 0, opacity: 0 }}
108	            animate={{ height: "auto", opacity: 1 }}
109	            exit={{ height: 0, opacity: 0 }}
110	            transition={{ duration: 0.28, ease: [0.22, 1, 0.36, 1] }}
111	            style={{ overflow: "hidden" } as React.CSSProperties}
112	          >
113	            <p
114	              style={{
115	                fontFamily: FONT.sans,
116	                fontSize: 15,
117	                lineHeight: 1.65,
118	                color: BRAND.stoneDark,
119	                padding: "0 24px 26px 44px",
120	                margin: 0,
121	              } as React.CSSProperties}
122	            >
123	              {item.a}
124	            </p>
125	          </motion.div>
126	        )}
127	      </AnimatePresence>
128	    </div>
129	  );
130	}
131	
132	export function FAQAccordion({
133	  items,
134	  defaultOpenIndex = 0,
135	  accent = "rust",
136	}: FAQAccordionProps) {
137	  const [openIdx, setOpenIdx] = useState<number | null>(defaultOpenIndex);
138	  const accentColor = ACCENT_MAP[accent].color;
139	
140	  return (
141	    <div
142	      style={{
143	        background: BRAND.white,
144	        borderRadius: 20,
145	        boxShadow: SHADOW.soft,
146	        maxWidth: 920,
147	        overflow: "hidden",
148	        width: "100%",
149	      } as React.CSSProperties}
150	    >
151	      {items.map((item, i) => (
152	        <div
153	          key={i}
154	          style={
155	            i === items.length - 1
156	              ? ({ borderBottom: "none" } as React.CSSProperties)
157	              : undefined
158	          }
159	        >
160	          <FAQRow
161	            item={item}
162	            index={i}
163	            isOpen={openIdx === i}
164	            onToggle={() => setOpenIdx(openIdx === i ? null : i)}
165	            accentColor={accentColor}
166	          />
167	        </div>
168	      ))}
169	    </div>
170	  );
171	}
