import type { Metadata } from "next";

export const metadata: Metadata = {
  title: "For Solo Artists — One chair, full kit, $29/mo | InkOS",
  description:
    "Tattoo studio software for the solo artist. Bookings, deposits, consent, photo timeline — everything you need to run one chair, no overhead.",
  openGraph: {
    title: "InkOS for Solo Artists",
    description: "One chair, full kit, $29/mo.",
    type: "website",
  },
  alternates: { canonical: "https://inkos.studio/for/solo-artists" },
};

export default function Layout({
  children,
}: Readonly<{ children: React.ReactNode }>) {
  return children;
}

"use client";

import React from "react";
import { motion } from "framer-motion";
import { AlertCircle, DollarSign, ImageIcon, Check, ArrowRight } from "lucide-react";
import { BRAND, FONT, SHADOW, GRADIENT, fadeUp, stagger } from "@/lib/brand";
import { Nav } from "@/components/layout/nav";
import { Footer } from "@/components/layout/footer";
import { HeroSection } from "@/components/shared/hero-section";
import { FAQAccordion } from "@/components/shared/faq-accordion";
import { CTASection } from "@/components/shared/cta-section";
import { SectionEyebrow } from "@/components/shared/section-eyebrow";
import { TestimonialCard } from "@/components/shared/testimonial-card";

// ── MoatCardBright (lifted from home/work.tsx) ────────────────────────────────

interface MoatCardBrightProps {
  accent: "rust" | "amber" | "sage";
  icon: React.ComponentType<{ size?: number; color?: string; strokeWidth?: number }>;
  title: string;
  body: string;
  detail: [string, string][];
}

const accentMap = {
  rust:  { color: BRAND.rust,  bg: BRAND.rustWash,  glow: GRADIENT.cardRust  },
  amber: { color: BRAND.amber, bg: BRAND.amberWash, glow: GRADIENT.cardAmber },
  sage:  { color: BRAND.sage,  bg: BRAND.sageWash,  glow: GRADIENT.cardSage  },
} as const;

function MoatCardBright({ accent, icon: Icon, title, body, detail }: MoatCardBrightProps) {
  const a = accentMap[accent];
  return (
    <motion.div
      initial={{ opacity: 0, y: 16 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true }}
      transition={{ duration: 0.5 }}
      whileHover={{ y: -4, boxShadow: SHADOW.card }}
      style={{
        background: BRAND.white,
        borderRadius: 18,
        padding: 28,
        boxShadow: SHADOW.soft,
        display: "flex",
        flexDirection: "column",
        gap: 18,
        position: "relative",
        overflow: "hidden",
        transition: "transform 0.25s, box-shadow 0.25s",
      } as React.CSSProperties}
    >
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          height: 3,
          background: a.color,
        } as React.CSSProperties}
      />
      <div
        aria-hidden="true"
        style={{
          position: "absolute",
          top: 0,
          right: 0,
          width: 120,
          height: 120,
          background: `radial-gradient(circle at 100% 0%, ${a.bg} 0%, transparent 70%)`,
          pointerEvents: "none",
        } as React.CSSProperties}
      />
      <div style={{ position: "relative" } as React.CSSProperties}>
        <div
          style={{
            width: 48,
            height: 48,
            borderRadius: 12,
            background: a.glow,
            border: `1px solid ${a.color}25`,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          } as React.CSSProperties}
        >
          <Icon size={20} color={a.color} strokeWidth={2} />
        </div>
      </div>
      <div style={{ position: "relative" } as React.CSSProperties}>
        <h3
          style={{
            fontFamily: FONT.sans,
            fontSize: 19,
            fontWeight: 600,
            color: BRAND.onyx,
            letterSpacing: "-0.015em",
            marginBottom: 10,
            lineHeight: 1.25,
          } as React.CSSProperties}
        >
          {title}
        </h3>
        <p
          style={{
            fontFamily: FONT.sans,
            fontSize: 14,
            fontWeight: 400,
            lineHeight: 1.6,
            color: BRAND.stoneDark,
          } as React.CSSProperties}
        >
          {body}
        </p>
      </div>
      <div
        style={{
          background: a.bg,
          borderRadius: 12,
          padding: "4px 16px",
          marginTop: "auto",
          position: "relative",
        } as React.CSSProperties}
      >
        {detail.map((row, i) => (
          <div
            key={i}
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "baseline",
              padding: "10px 0",
              borderBottom: i < detail.length - 1 ? `1px dashed ${a.color}25` : "none",
              gap: 12,
            } as React.CSSProperties}
          >
            <span
              style={{
                fontFamily: FONT.sans,
                fontSize: 11.5,
                fontWeight: 500,
                color: BRAND.stoneDark,
              } as React.CSSProperties}
            >
              {row[0]}
            </span>
            <span
              style={{
                fontFamily: FONT.sans,
                fontSize: 12,
                fontWeight: 600,
                color: BRAND.onyx,
                textAlign: "right",
              } as React.CSSProperties}
            >
              {row[1]}
            </span>
          </div>
        ))}
      </div>
    </motion.div>
  );
}

// ── Pain Points ───────────────────────────────────────────────────────────────

function PainPointsSection() {
  return (
    <section
      style={{
        background: GRADIENT.sectionWarm,
        paddingTop: 100,
        paddingBottom: 100,
        position: "relative",
        overflow: "hidden",
      } as React.CSSProperties}
    >
      <div
        style={{
          maxWidth: 1120,
          margin: "0 auto",
          padding: "0 32px",
        } as React.CSSProperties}
      >
        <motion.div
          initial={{ opacity: 0, y: 16 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: "-80px" }}
          transition={{ duration: 0.6 }}
          style={{ marginBottom: 48 } as React.CSSProperties}
        >
          <SectionEyebrow label="What you're tired of" accent="amber" />
          <h2
            style={{
              fontFamily: FONT.serif,
              fontSize: "clamp(32px, 4vw, 48px)",
              fontWeight: 400,
              color: BRAND.onyx,
              letterSpacing: "-0.025em",
              lineHeight: 1.1,
              maxWidth: 600,
            } as React.CSSProperties}
          >
            Sound familiar?
          </h2>
        </motion.div>

        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(3, 1fr)",
            gap: 18,
          } as React.CSSProperties}
          className="v4-moat-grid"
        >
          <MoatCardBright
            accent="rust"
            icon={AlertCircle}
            title="Six apps before 10:30"
            body="Booking on one site. Deposits in another. Consent on paper. Allergy in your Notes. The work hasn't started."
            detail={[
              ["Apps usually", "5–7"],
              ["Time lost", "~40 min"],
              ["Mental load", "high"],
            ]}
          />
          <MoatCardBright
            accent="amber"
            icon={DollarSign}
            title="Deposit tracking by memory"
            body="Asha paid $200 last month, but for which session? Cash app vs Stripe. The spreadsheet you keep meaning to update."
            detail={[
              ["Spreadsheet status", "outdated"],
              ["Errors", "occasional"],
              ["Friday admin", "90 min"],
            ]}
          />
          <MoatCardBright
            accent="sage"
            icon={ImageIcon}
            title="Photos in your camera roll"
            body="REF, fresh, healed — all mixed in with your selfies and lunch photos. Finding 'the back piece from May' takes 8 minutes."
            detail={[
              ["Storage", "phone roll"],
              ["Searchability", "zero"],
              ["Backup", "hopefully"],
            ]}
          />
        </div>
      </div>
    </section>
  );
}

// ── Why InkOS ─────────────────────────────────────────────────────────────────

const soloFeatures = [
  "Today launchpad — see your day in 90 seconds",
  "Multi-session projects — sleeves tracked end to end",
  "Deposit pool — money lives on the project, not your spreadsheet",
  "Photo timeline — REF / FRESH / HEAL / HEALED, auto-organised",
  "Allergy intelligence — surfaced before the chair",
  "Stripe Connect — payouts in <2 days",
  "Email support — humans who answer in <24h",
];

function WhyInkOSSection() {
  return (
    <section
      style={{
        background: BRAND.bone,
        paddingTop: 100,
        paddingBottom: 100,
      } as React.CSSProperties}
    >
      <div
        style={{
          maxWidth: 1120,
          margin: "0 auto",
          padding: "0 32px",
        } as React.CSSProperties}
      >
        <motion.div
          initial={{ opacity: 0, y: 16 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: "-80px" }}
          transition={{ duration: 0.6 }}
          style={{ marginBottom: 48 } as React.CSSProperties}
        >
          <SectionEyebrow label="What changes" accent="sage" />
          <h2
            style={{
              fontFamily: FONT.serif,
              fontSize: "clamp(32px, 4vw, 48px)",
              fontWeight: 400,
              color: BRAND.onyx,
              letterSpacing: "-0.025em",
              lineHeight: 1.1,
            } as React.CSSProperties}
          >
            Solo plan, full kit.
          </h2>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 16 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.5 }}
          style={{
            background: BRAND.white,
            borderRadius: 20,
            padding: 32,
            boxShadow: SHADOW.soft,
            maxWidth: 720,
          } as React.CSSProperties}
        >
          <ul style={{ listStyle: "none", padding: 0, margin: 0 } as React.CSSProperties}>
            {soloFeatures.map((feature, i) => (
              <li
                key={i}
                style={{
                  display: "flex",
                  alignItems: "flex-start",
                  gap: 12,
                  paddingTop: i === 0 ? 0 : 14,
                  paddingBottom: i === soloFeatures.length - 1 ? 0 : 14,
                  borderBottom:
                    i < soloFeatures.length - 1
                      ? `1px solid ${BRAND.borderSoft}`
                      : "none",
                } as React.CSSProperties}
              >
                <div
                  style={{
                    width: 22,
                    height: 22,
                    borderRadius: "50%",
                    background: BRAND.sageWash,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    flexShrink: 0,
                    marginTop: 1,
                  } as React.CSSProperties}
                >
                  <Check size={13} color={BRAND.sage} strokeWidth={2.5} />
                </div>
                <span
                  style={{
                    fontFamily: FONT.sans,
                    fontSize: 15,
                    fontWeight: 400,
                    color: BRAND.ink,
                    lineHeight: 1.55,
                  } as React.CSSProperties}
                >
                  {feature}
                </span>
              </li>
            ))}
          </ul>
          <p
            style={{
              fontFamily: FONT.sans,
              fontSize: 13,
              color: BRAND.stoneDark,
              marginTop: 24,
              lineHeight: 1.5,
              borderTop: `1px solid ${BRAND.borderSoft}`,
              paddingTop: 20,
            } as React.CSSProperties}
          >
            Everything in this list comes with the $29 Solo plan. No add-ons, no platform fees.
          </p>
        </motion.div>
      </div>
    </section>
  );
}

// ── Customer Quote ─────────────────────────────────────────────────────────────

function CustomerQuoteSection() {
  return (
    <section
      style={{
        background: BRAND.bone,
        paddingTop: 80,
        paddingBottom: 80,
      } as React.CSSProperties}
    >
      <div
        style={{
          maxWidth: 1120,
          margin: "0 auto",
          padding: "0 32px",
        } as React.CSSProperties}
      >
        <motion.div
          initial={{ opacity: 0, y: 16 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: "-80px" }}
          transition={{ duration: 0.6 }}
          style={{ marginBottom: 32 } as React.CSSProperties}
        >
          <SectionEyebrow label="Real solo studio" accent="rust" />
          <h2
            style={{
              fontFamily: FONT.serif,
              fontSize: "clamp(28px, 3.5vw, 42px)",
              fontWeight: 400,
              color: BRAND.onyx,
              letterSpacing: "-0.025em",
              lineHeight: 1.1,
            } as React.CSSProperties}
          >
            How Kaia runs Nine Lives.
          </h2>
        </motion.div>

        <motion.div
          variants={fadeUp}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true }}
          style={{ maxWidth: 460 } as React.CSSProperties}
        >
          <TestimonialCard
            name="Kaia Osei"
            role="Solo · Nine Lives Tattoo"
            city="East London, UK"
            chairs="1 chair · resident-only"
            quote="My whole week starts with a six-minute triage now. Inbox sorts the urgent stuff before I've even opened the shop."
